original_aql:
LET businesses = (
    FOR b IN Businesses
        RETURN {
            business_id: b.business_id,
            category_count: COUNT(FOR c IN 1..1 OUTBOUND b BusinessCategory)
        }
)

SORT businesses BY category_count DESC
LIMIT 1

RETURN businesses[0].business_id

